mapper.select:
SELECT distinct
bok.BOOKSET_ID AS PROD_ID, /** 账套代码 **/ NVL(bok.BOOKSET_NAME,bok.BOOKSET_FULLNAME) AS PROD_NAME, /** 产品名称 **/ VAL.PORTFOLIO_ID AS PORTFOLIO_ID, /** 组合代码 **/
NVL(fin.FINPROD_ID,trdfin.FINPROD_ID) AS FINPROD_ID, /** 金融产品代码 **/ NVL(fin.Finprod_Type,trdfin.Finprod_Type) AS Finprod_Type, /** 金融产品类型 **/ NVL(fin.FINPROD_MARKET_ID,trdfin.FINPROD_ID) AS FINPROD_MARKET_ID,/** 市场代码 **/ NVL(fin.VDATE,trdfin.VDATE) AS VDATE, /** 起息日 **/ NVL(fin.MDATE,trdfin.MDATE) AS MDATE, /** 到期日 **/ finAdd.IS_EFF_PLEDGE AS IS_LIMITS, /** 是否含有抵质押物 **/ finadd.BOND_RISK_TYPE AS FIRST_RESULT, /** 风险五级分类 **/ fin.COUPON_SPECIES AS COUPON_SPECIES, /** 息票品种 **/ fin.ISSUE_PRICE AS ISSUE_PRICE, /** 发行价 **/ fin.ISSUE_AMT AS ISSUE_AMT, /** 发行数量 **/ NVL(fin.ISSUER, trdfin.COUNTER_ID) AS ISSUER, /** 发行人/交易对手（回购）**/ cust1.IS_FIN_LICENCE AS ISSUER_FIN_LICENCE, fin.FINANCIER AS FINANCIER, cust2.IS_FIN_LICENCE AS FINANCIER_FIN_LICENCE, fin.SPONSOR AS SPONSOR, cust3.IS_FIN_LICENCE AS SPONSOR_FIN_LICENCE, typ.TYPE_1 AS SEC_DETAIL_TYPE_MODEL, /** 模型证券细分类 **/ typ.TYPE_18 AS SEC_TYPE_MODEL, /** 模型资产类型 **/ DECODE(VAL.INV_AIM,'999999',NULL,VAL.INV_AIM) AS INV_AIM FROM PTL_SEC_VALUTION VAL INNER JOIN BOK_BOOKSET bok ON (bok.BOOKSET_ID = VAL.PORTFOLIO_ID OR bok.BOOKSET_ID = 'F16_'||VAL.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT fin ON fin.FINPROD_ID = VAL.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT trdfin ON trdfin.FINPROD_ID = VAL.FINPROD_ID AND trdfin.BRANCH = 0 LEFT JOIN FIN_PRODUCT_ADD finadd ON VAL.FINPROD_ID = finadd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE typ ON VAL.FINPROD_ID = typ.FINPROD_ID AND typ.BRANCH = 0 LEFT JOIN MST_CUSTOMER_INFO_ADD cust1 ON fin.ISSUER = cust1.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD cust2 ON fin.FINANCIER = cust2.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD cust3 ON fin.SPONSOR = cust3.CUSTOMER_ID WHERE 1=1 AND VAL.DSC_COST_AMT != 0 AND VAL.CDATE = #{searchDate} -1 AND VAL.INV_AIM IN ('AC','FVOCI','999999') AND ( typ.TYPE_18 IN (#{SEC_TYPE_01}，#{SEC_TYPE_13}) --债券、其他债权类 OR (typ.TYPE_18 = #{SEC_TYPE_07} AND fin.TYPE_1 IN ('01','03')) --存款类资产：存放同业、同业借款 OR (typ.TYPE_18 = #{SEC_TYPE_09} AND fin.TYPE_1 IN ('02','04')) --回购类资产：质押式逆回购、买断式逆回购 ) AND NVL(fin.VDATE,trdfin.VDATE) <= #{searchDate} AND NVL(NVL(fin.MDATE,trdfin.MDATE) , #{searchDate}+1)> #{searchDate}
AND (a.FINPROD_ID IN
null) OR a.FINPROD_ID in (
#{item}
)

SELECT distinct --产品信息 --> bok.BOOKSET_ID AS PROD_ID, NVL(bok.BOOKSET_NAME,bok.BOOKSET_FULLNAME) AS PROD_NAME, NVL(prodAdd.PORTFOLIO_ID,bok.ACCT_SUBJECT_ID) AS PORTFOLIO_ID, --资产信息 --> NVL(fin.FINPROD_ID,trdfin.FINPROD_ID) AS FINPROD_ID, NVL(fin.Finprod_Type,trdfin.Finprod_Type) AS Finprod_Type, NVL(fin.FINPROD_MARKET_ID,trdfin.FINPROD_ID) AS FINPROD_MARKET_ID, NVL(fin.VDATE,trdfin.VDATE) AS VDATE, NVL(fin.MDATE,trdfin.MDATE) AS MDATE, finAdd.IS_EFF_PLEDGE AS IS_LIMITS, finadd.BOND_RISK_TYPE AS FIRST_RESULT, fin.COUPON_SPECIES AS COUPON_SPECIES, fin.ISSUE_PRICE AS ISSUE_PRICE, fin.ISSUE_AMT AS ISSUE_AMT, NVL(fin.ISSUER, trdfin.COUNTER_ID) AS ISSUER, /** 发行人/交易对手（回购）**/ cust1.IS_FIN_LICENCE AS ISSUER_FIN_LICENCE, fin.FINANCIER AS FINANCIER, cust2.IS_FIN_LICENCE AS FINANCIER_FIN_LICENCE, fin.SPONSOR AS SPONSOR, cust3.IS_FIN_LICENCE AS SPONSOR_FIN_LICENCE, typ.TYPE_1 AS SEC_DETAIL_TYPE_MODEL, typ.TYPE_18 AS SEC_TYPE_MODEL, deal.SETTLE_DATE AS SETTLE_DATE, ACC.INV_AIM AS INV_AIM FROM TRD_PRODUCT_DEAL DEAL INNER JOIN BOK_DEAL_ACCOUNTING ACC ON ACC.BUSI_NO = DEAL.TRADE_ID INNER JOIN BOK_BOOKSET bok ON BOK.BOOKSET_ID = ACC.BOOKSET_ID LEFT JOIN FIN_PRODUCT_ADD prodAdd ON prodAdd.FINPROD_ID = bok.ACCT_SUBJECT_ID LEFT JOIN PTL_SEC_VALUTION VAL ON VAL.PORTFOLIO_ID = NVL(prodAdd.PORTFOLIO_ID,bok.ACCT_SUBJECT_ID) AND VAL.FINPROD_ID = deal.FINPROD_ID AND VAL.DSC_COST_AMT != 0 AND VAL.CDATE = #{searchDate} -1 AND DECODE(VAL.INV_AIM,'999999',NULL,VAL.INV_AIM) = ACC.INV_AIM LEFT JOIN FIN_PRODUCT fin ON fin.finprod_id = DEAL.Finprod_Id LEFT JOIN FIN_TRADE_PRODUCT trdfin ON trdfin.finprod_id = DEAL.FINPROD_ID AND trdfin.branch = 0 LEFT JOIN FIN_PRODUCT_ADD finadd ON DEAL.FINPROD_ID = finadd.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE typ ON DEAL.FINPROD_ID = typ.FINPROD_ID AND typ.BRANCH = 0 LEFT JOIN MST_CUSTOMER_INFO_ADD cust1 ON fin.ISSUER = cust1.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD cust2 ON fin.FINANCIER = cust2.CUSTOMER_ID LEFT JOIN MST_CUSTOMER_INFO_ADD cust3 ON fin.SPONSOR = cust3.CUSTOMER_ID WHERE 1=1 AND VAL.Portfolio_Id IS NULL AND DEAL.PS IN ('T01','T35') AND ACC.INV_AIM != 'FVTPL' AND DEAL.TRADE_DATE = #{searchDate} AND ( typ.TYPE_18 IN (#{SEC_TYPE_01}，#{SEC_TYPE_13}) --债券、其他债权类 OR (typ.TYPE_18 = #{SEC_TYPE_07} AND fin.TYPE_1 IN ('01','03')) --存款类资产：存放同业、同业借款 OR (typ.TYPE_18 = #{SEC_TYPE_09} AND fin.TYPE_1 IN ('02','04')) --回购类资产：质押式逆回购、买断式逆回购 )
AND (a.FINPROD_ID IN
null) OR a.FINPROD_ID in (
#{item}
)

SELECT MIN(A.TRADE_DATE)
FROM TRD_PRODUCT_DEAL A
INNER JOIN BOK_DEAL_ACCOUNTING ACC
 ON ACC.BUSI_NO = A.TRADE_ID
WHERE A.PS='T01'
	AND A.FINPROD_ID=#{finprodId}
  	AND A.TRADE_DATE >= NVL(
		(
				SELECT MAX(B.CDATE) FROM PTL_SEC_VALUTION B
				WHERE B.DSC_COST_AMT = 0
					AND B.FINPROD_ID=#{finprodId}
				  	AND B.PORTFOLIO_ID=#{portfolioId})
		),A.TRADE_DATE
	)
	AND ACC.BOOKSET_ID = #{prodId}
